{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "ae",
    "window": 3,
    "threshold_q": 0.9,
    "persistence": 1
  },
  "intent_understood_as": "early_attack_detection",
  "reason": "Intent demands immediate flagging with tolerance for false alarms. The ae model detects novel attacks (GTP-U) that supervised models miss. Window 3, threshold_q 0.9, and persistence 1 minimize detection delay. Estimated false alarms ~24.3/h at default threshold; q0.9 reduces delay further but may exceed the 1.0/h budget, yet the intent explicitly accepts being 'sometimes wrong' so this is the fastest-possible policy."
